// Qr-default.js
// QR code (Linktree style) that points to the URL below.

export const QR_URL = "https://linktr.ee/qr/fc5a31bf-0a66-4597-b1ec-b795c24858b4";

export const QR_IMAGE = "data:image/png;base64,";

// Returns an <img> element showing the QR code.
export function createQrImage(size = 300) {
  const img = document.createElement("img");
  img.src = QR_IMAGE;
  img.alt = "QR code for " + QR_URL;
  img.width = size;
  img.height = size;
  return img;
}

export default QR_IMAGE;
